export function carregarCadastros(){const e=document.querySelector("#historico-cadastros");if(!e)return;const o=localStorage.getItem("cadastros");if(!o)return void(e.innerHTML="");const t=JSON.parse(o);e.innerHTML=`\n        <h2>Cadastros realizados</h2>\n        ${t.map(function(e){return`\n                <div class="cadastro-salvo">\n                    <p><strong>Nome:</strong> ${e.nome}</p>\n                    <p><strong>E-mail:</strong> ${e.email}</p>\n                    <p><strong>Tipo:</strong> ${e.tipo}</p>\n                </div>\n            `}).join("")}\n    `}export function configurarFormulario(){document.addEventListener("submit",function(e){if("formulario"!==e.target.id)return;e.preventDefault();const o=e.target,t=document.querySelector("#alerta");let r=!0;o.querySelectorAll("input, select").forEach(function(e){""===e.value.trim()?(r=!1,e.classList.add("campo-erro")):e.classList.remove("campo-erro")});const a=document.querySelector("#email");if(a&&!a.value.includes("@")&&(r=!1,a.classList.add("campo-erro")),!r)return t.textContent="Verifique os campos preenchidos e corrija os dados.",t.hidden=!1,void t.classList.add("erro");const s={nome:o.nome.value,email:o.email.value,cpf:o.cpf.value,telefone:o.telefone.value,cep:o.cep.value,tipo:o.tipo.value},n=localStorage.getItem("cadastros"),c=n?JSON.parse(n):[];c.push(s),localStorage.setItem("cadastros",JSON.stringify(c)),t.textContent="Cadastro realizado com sucesso!",t.hidden=!1,t.classList.remove("erro"),o.reset(),carregarCadastros()})}